/// `nvgpu.tma.async.store`: TMA asynchronous store
///
/// The Op store a tile memory region from global memory to shared memory by
/// Tensor Memory Access (TMA).
///
/// `$tensorMapDescriptor` is tensor map descriptor which has information about
/// tile shape. The descriptor is created by `nvgpu.tma.create.descriptor`
#[mlir::op("nvgpu.tma.async.store", format = "$src `to` $tensorMapDescriptor `[` $coordinates `]` (`,` `predicate` `=` $predicate^)? attr-dict `:` type($src) `->` type($tensorMapDescriptor)")]
pub struct TmaAsyncStoreOp<'a> {
    #[slot(src_ty)]
    pub src: Value<'a>,
    #[slot(tensor_map_descriptor_ty, name = "tensorMapDescriptor")]
    pub tensor_map_descriptor: Value<'a>,
    #[slot(coordinates_ty)]
    pub coordinates: Vec<Value<'a>>,
    #[slot(predicate_ty)]
    pub predicate: Vec<Value<'a>>,
    pub src_ty: Type<'a>,
    #[dtype(strip = "nvgpu.tensormap.descriptor")]
    pub tensor_map_descriptor_ty: Type<'a>,
    #[dtype(is = index)]
    pub coordinates_ty: Type<'a>,
    #[dtype(is = i1)]
    pub predicate_ty: Type<'a>,
}

/// `nvgpu.tma.create.descriptor`: TMA create descriptor
///
/// The Op creates a tensor map descriptor object representing tiled memory
/// region. To do that it calls CUDA Driver's `cuTensorMapEncodeTiled`. The
/// descriptor is used by Tensor Memory Access (TMA).
///
/// The `tensor` is the source tensor to be tiled.
///
/// The `boxDimensions` is the size of the tiled memory region in each dimension.
///
/// For more information see below:
/// https://docs.nvidia.com/cuda/cuda-driver-api/group__CUDA__TENSOR__MEMORY.html
#[mlir::op("nvgpu.tma.create.descriptor", format = "$tensor `box` `[` $boxDimensions `]` attr-dict `:` type($tensor) `->` type($tensorMap)", results(tensor_map))]
pub struct TmaCreateDescriptorOp<'a> {
    #[slot(tensor_ty)]
    pub tensor: Value<'a>,
    #[slot(box_dimensions_ty, name = "boxDimensions")]
    pub box_dimensions: Vec<Value<'a>>,
    pub tensor_ty: Type<'a>,
    #[dtype(is = index)]
    pub box_dimensions_ty: Type<'a>,
    #[dtype(name = "tensorMap", strip = "nvgpu.tensormap.descriptor")]
    pub tensor_map: Type<'a>,
}

/// `nvgpu.tma.fence.descriptor`: Insert fence given `nvgpu.tensormap.descriptor`
///
/// The Op fences the given `$tmaDescriptor`. This is necessary if the tensor map
/// descriptor was modified from the host using cudaMemcpy. In this case, the
/// kernel needs a fence after which it is safe to use `tensor.map`.
#[mlir::op("nvgpu.tma.fence.descriptor", format = "$tensorMapDescriptor attr-dict `:` type($tensorMapDescriptor)")]
pub struct TmaFenceOp<'a> {
    #[slot(tensor_map_descriptor_ty, name = "tensorMapDescriptor")]
    pub tensor_map_descriptor: Value<'a>,
    #[dtype(strip = "nvgpu.tensormap.descriptor")]
    pub tensor_map_descriptor_ty: Type<'a>,
}

/// `nvgpu.tma.prefetch.descriptor`: Prefetch given `nvgpu.tensormap.descriptor`
///
/// The Op brings the cache line containing the given `$tmaDescriptor` for
/// subsequent use by the `tma.async.load` instruction.
#[mlir::op("nvgpu.tma.prefetch.descriptor", format = "$tensorMapDescriptor (`,` `predicate` `=` $predicate^)? attr-dict `:` type($tensorMapDescriptor)")]
pub struct TmaPrefetchOp<'a> {
    #[slot(tensor_map_descriptor_ty, name = "tensorMapDescriptor")]
    pub tensor_map_descriptor: Value<'a>,
    #[slot(predicate_ty)]
    pub predicate: Vec<Value<'a>>,
    #[dtype(strip = "nvgpu.tensormap.descriptor")]
    pub tensor_map_descriptor_ty: Type<'a>,
    #[dtype(is = i1)]
    pub predicate_ty: Type<'a>,
}

/// `nvgpu.warpgroup.generate.descriptor`: Generate a warpgroup matrix descriptor
///
/// This Op builds a `nvgpu.warpgroup.descriptor` that is used by
/// `nvgpu.warpgroup.mma` to perform warpgroup-level matrix multiply and
/// accumulate.
///
/// The descriptor specifies the properties of the matrix in shared memory that
/// is a multiplicand in the matrix multiply and accumulate operation.
#[mlir::op("nvgpu.warpgroup.generate.descriptor", format = "$tensor `,` $tensorMap attr-dict `:` type($tensor) `,` type($tensorMap) `->` type($descriptor)", results(descriptor))]
pub struct WarpgroupGenerateDescriptorOp<'a> {
    #[slot(tensor_ty)]
    pub tensor: Value<'a>,
    #[slot(tensor_map_ty, name = "tensorMap")]
    pub tensor_map: Value<'a>,
    pub tensor_ty: Type<'a>,
    #[dtype(strip = "nvgpu.tensormap.descriptor")]
    pub tensor_map_ty: Type<'a>,
    #[dtype(strip = "nvgpu.warpgroup.descriptor")]
    pub descriptor: Type<'a>,
}

/// `nvgpu.warpgroup.mma.init.accumulator`: Initializes the accumulator matrix
///
/// This Op generates and initializes the accumulator matrix for
/// `nvgpu.warpgroup.mma` op to perform matrix-multiply-and-accumulate.
#[mlir::op("nvgpu.warpgroup.mma.init.accumulator", format = "attr-dict `->` type($matrixC)", results(matrix_c))]
pub struct WarpgroupMmaInitAccumulatorOp<'a> {
    #[dtype(name = "matrixC", strip = "nvgpu.warpgroup.accumulator")]
    pub matrix_c: Type<'a>,
}

///
/// The `nvgpu.warpgroup.mma` op performs the warpgroup-level (4 warps)
/// matrix-multiply-and-accumulate (mma) operation that results in
/// `nvvm.wgmma.mma_async`.
///
/// The operands are `descriptorA` and `descriptorB` that are wgmma matrix
/// descriptors that shows the properties of the matrix in shared memory. The
/// results are thread-level ownership to the warpgroup-level mma operation
/// shape. The shape is deduced from the descriptor types and output vector.
///
/// The Op encapsulates multiple `nvvm.wgmma.mma_async` operations to complete
/// the given shape. As `nvvm.wgmma.async` Op, or its corresponding PTX
/// instruction, is asynchronous, this Op groups the `nvvm.wgmma.async` and
/// surrounds them between `wgmma.fence.aligned` and
/// `wgmma.commit.group.sync.aligned`, `wgmma.wait.group.sync.aligned` Ops.
///
/// Example:
/// ```mlir
///   %r1,%r2 = nvgpu.warpgroup.mma %descA, %descB, %acc1, %acc2:
///              !nvgpu.warpgroup.descriptor<tensor = memref<128x64xf16, 3>>,
///              !nvgpu.warpgroup.descriptor<tensor = memref<64x128xf16, 3>>,
///              !nvgpu.warpgroup.accumulator<fragmented = vector<64x128xf32>>,
///              !nvgpu.warpgroup.accumulator<fragmented = vector<64x128xf32>>
///              ->
///              !nvgpu.warpgroup.accumulator<fragmented = vector<64x128xf32>>,
///              !nvgpu.warpgroup.accumulator<fragmented = vector<64x128xf32>>
/// ```
#[mlir::op("nvgpu.warpgroup.mma", format = "$descriptorA`,` $descriptorB`,` $matrixC attr-dict `:` type($descriptorA) `,` type($descriptorB) `,` type($matrixC) `->` type($matrixD)", results(matrix_d))]
pub struct WarpgroupMmaOp<'a> {
    #[slot(descriptor_a_ty, name = "descriptorA")]
    pub descriptor_a: Value<'a>,
    #[slot(descriptor_b_ty, name = "descriptorB")]
    pub descriptor_b: Value<'a>,
    #[slot(matrix_c_ty, name = "matrixC")]
    pub matrix_c: Value<'a>,
    #[attr(name = "waitGroup", int = "i64")]
    pub wait_group: Option<Attribute<'a>>,
    #[attr(name = "transposeA")]
    pub transpose_a: bool,
    #[attr(name = "transposeB")]
    pub transpose_b: bool,
    #[dtype(strip = "nvgpu.warpgroup.descriptor")]
    pub descriptor_a_ty: Type<'a>,
    #[dtype(strip = "nvgpu.warpgroup.descriptor")]
    pub descriptor_b_ty: Type<'a>,
    #[dtype(strip = "nvgpu.warpgroup.accumulator")]
    pub matrix_c_ty: Type<'a>,
    #[dtype(name = "matrixD", strip = "nvgpu.warpgroup.accumulator")]
    pub matrix_d: Type<'a>,
}

///
/// The `nvgpu.warpgroup.mma.store` op performs the store of fragmented result
/// in $matrixD to given memref.
///
/// [See the details of register fragment layout for accumulator matrix D]
/// (https://docs.nvidia.com/cuda/parallel-thread-execution/index.html#wgmma-64n16-d)
///
/// Note that, the op must be run with warp group.
#[mlir::op("nvgpu.warpgroup.mma.store", format = "$matrixD `,` $dstMemref attr-dict `:` type($matrixD) `to` type($dstMemref)")]
pub struct WarpgroupMmaStoreOp<'a> {
    #[slot(matrix_d_ty, name = "matrixD")]
    pub matrix_d: Value<'a>,
    #[slot(dst_memref_ty, name = "dstMemref")]
    pub dst_memref: Value<'a>,
    #[dtype(strip = "nvgpu.warpgroup.accumulator")]
    pub matrix_d_ty: Type<'a>,
    pub dst_memref_ty: Type<'a>,
}

/// The `nvgpu` dialect.
#[mlir::dialect(
    "nvgpu",
    ops = [DeviceAsyncCopyOp, DeviceAsyncCreateGroupOp, DeviceAsyncWaitOp, LdMatrixOp, MBarrierArriveExpectTxOp, MBarrierArriveNoCompleteOp, MBarrierArriveOp, MBarrierCreateOp, MBarrierGetOp, MBarrierInitOp, MBarrierTestWaitOp, MBarrierTryWaitParityOp, MmaSparseSyncOp, MmaSyncOp, RcpOp, TmaAsyncLoadOp, TmaAsyncStoreOp, TmaCreateDescriptorOp, TmaFenceOp, TmaPrefetchOp, WarpgroupGenerateDescriptorOp, WarpgroupMmaInitAccumulatorOp, WarpgroupMmaOp, WarpgroupMmaStoreOp]
)]
pub struct NvgpuDialect;
